import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { T } from "./constants";

export default function LoginPage() {
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async () => {
    if (!email || !pass) {
      setErr("يرجى إدخال البريد الإلكتروني وكلمة المرور");
      return;
    }

    try {
      setLoading(true);
      setErr("");

      const response = await axios.post(
        "http://localhost:8000/login",
        {
          email,
          password: pass,
        },
        {
          withCredentials: true,
        }
      );

      console.log(response.data);

      // login success
      if (response.status === 200) {

        // save user if needed
        localStorage.setItem(
          "admin",
          JSON.stringify(response.data.user)
        );

        // navigate to dashboard
        navigate("/admin-dashboard");
      }

    } catch (error) {
      console.log(error);

      if (error.response) {
        setErr(error.response.data.message);
      } else {
        setErr("حدث خطأ في الاتصال بالسيرفر");
      }

    } finally {
      setLoading(false);
    }
  };

  const styles = {
    root: {
      minHeight: "100vh",
      background:
        "linear-gradient(135deg, #1a0000 0%, #B71C1C 50%, #7B0000 100%)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "'Cairo', sans-serif",
      direction: "rtl",
      padding: "20px",
      position: "relative",
      overflow: "hidden",
    },

    pattern: {
      position: "absolute",
      inset: 0,
      opacity: 0.04,
      backgroundImage:
        "repeating-linear-gradient(45deg,#fff 0,#fff 1px,transparent 0,transparent 50%)",
      backgroundSize: "18px 18px",
      pointerEvents: "none",
    },

    watermark: {
      position: "absolute",
      right: "-40px",
      bottom: "-60px",
      fontFamily: "'Noto Serif SC', serif",
      fontSize: "280px",
      color: "rgba(255,255,255,0.04)",
      fontWeight: 700,
      lineHeight: 1,
      pointerEvents: "none",
      userSelect: "none",
    },

    card: {
      background: "#fff",
      borderRadius: "20px",
      padding: "48px 44px",
      width: "100%",
      maxWidth: "420px",
      boxShadow: "0 24px 80px rgba(0,0,0,0.35)",
      position: "relative",
      zIndex: 2,
    },

    input: {
      width: "100%",
      padding: "12px 14px",
      border: `1.5px solid ${T.border}`,
      borderRadius: "10px",
      fontSize: "14px",
      marginBottom: "18px",
    },

    btn: {
      width: "100%",
      padding: "13px",
      background: T.red,
      color: "#fff",
      border: "none",
      borderRadius: "10px",
      cursor: "pointer",
    },

    err: {
      background: "#ffebee",
      color: "#c62828",
      borderRadius: "8px",
      padding: "10px",
      marginTop: "15px",
      textAlign: "center",
    },
  };

  return (
    <div style={styles.root}>
      <div style={styles.pattern} />
      <div style={styles.watermark}>孔</div>

      <div style={styles.card}>
        <h2>لوحة تحكم الإدارة</h2>

        <input
          type="email"
          placeholder="البريد الإلكتروني"
          style={styles.input}
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />

        <input
          type="password"
          placeholder="كلمة المرور"
          style={styles.input}
          value={pass}
          onChange={(e) => setPass(e.target.value)}
        />

        <button
          onClick={submit}
          style={styles.btn}
          disabled={loading}
        >
          {loading ? "جاري التحقق..." : "تسجيل الدخول"}
        </button>

        {err && <div style={styles.err}>{err}</div>}
      </div>
    </div>
  );
}
